// THE 8-STEP HARD PROBLEM FRAMEWORK
// Applied to: Largest Rectangle in Histogram (#84)

// STEP 1: Read twice
// Given n non-negative integers representing histogram bar heights (width=1),
// find the largest rectangle that can be formed within the histogram.

// STEP 2: Concrete examples
// [2,1,5,6,2,3]: answer = 10 (5x2 rectangle using bars 5 and 6)
// [2,4]: answer = 4 (4x1)
// []: answer = 0 (edge case)

// STEP 3: Constraints
// n up to 10^5, heights up to 10^4
// O(n^2): try all pairs of left and right boundaries -> TLE for n=10^5
// O(n^3): explicit: TLE
// Need O(n log n) or O(n)

// STEP 4: Simplify (n=3)
// [3, 1, 2]: max rect = 3 (bar 0 alone) or 2 (bars 0-2 with height 1) or 2 (bar 2 alone)
// Bar 1 (height 1) limits the rectangle spanning all 3 bars
// For each bar as the SHORTEST bar, find how far left and right it extends

// STEP 5: Pattern family
// Each bar's maximum rectangle = bar_height * (right_boundary - left_boundary)
// Need: previous smaller and next smaller element for each bar
// -> Monotonic stack

// STEP 6: The INSIGHT
// For each bar h[i], the largest rectangle with h[i] as the minimum height
// extends from the previous smaller bar (exclusive) to the next smaller bar (exclusive)
// Use a monotonic stack to find previous/next smaller in O(n)

// STEP 7: Implement
function largestRectangleArea(heights) {
    const n = heights.length;
    heights = [...heights, 0]; // sentinel 0 to flush stack
    const stack = []; // monotonic increasing stack of indices
    let maxArea = 0;

    for (let i = 0; i <= n; i++) {
        while (stack.length && heights[stack[stack.length-1]] > heights[i]) {
            const h = heights[stack.pop()];
            const w = stack.length ? i - stack[stack.length-1] - 1 : i;
            maxArea = Math.max(maxArea, h * w);
        }
        stack.push(i);
    }
    return maxArea;
}

// STEP 8: Test
console.log(largestRectangleArea([2,1,5,6,2,3])); // 10 ✓
console.log(largestRectangleArea([2,4]));           // 4 ✓
console.log(largestRectangleArea([]));              // 0 ✓

// STRESS TEST: compare with brute force
function bruteForce(heights) {
    let max = 0;
    for (let i=0;i<heights.length;i++) {
        let min = heights[i];
        for (let j=i;j<heights.length;j++) {
            min = Math.min(min,heights[j]);
            max = Math.max(max, min*(j-i+1));
        }
    }
    return max;
}
// Stress test with 1000 random inputs
let failures = 0;
for (let t=0;t<1000;t++) {
    const h = Array.from({length:6},()=>Math.floor(Math.random()*10));
    if (largestRectangleArea(h) !== bruteForce(h)) failures++;
}
console.log(`Stress test: ${failures} failures (should be 0)`);

