// WEEK 2 SELECTED IMPLEMENTATIONS

// PROBLEM 20: DUNGEON GAME (#174)
// INSIGHT: DP must go bottom-right to top-left
// dp[i][j] = minimum health needed to reach dungeon[i][j] alive
function calculateMinimumHP(dungeon) {
    const m=dungeon.length, n=dungeon[0].length;
    const dp = Array.from({length:m+1},()=>new Array(n+1).fill(Infinity));
    dp[m][n-1] = dp[m-1][n] = 1; // boundary: need 1 health to enter princess room
    for (let i=m-1;i>=0;i--) {
        for (let j=n-1;j>=0;j--) {
            const minNext = Math.min(dp[i+1][j], dp[i][j+1]);
            dp[i][j] = Math.max(1, minNext - dungeon[i][j]);
        }
    }
    return dp[0][0];
}
console.log(calculateMinimumHP([[-2,-3,3],[-5,-10,1],[10,30,-5]])); // 7

// PROBLEM 19: MINIMUM REFUELING STOPS (#871)
// INSIGHT: greedy with max-heap — refuel at richest station seen so far
function minRefuelStops(target, startFuel, stations) {
    const heap = []; // max-heap of fuel amounts
    // Use sorted array as priority queue for simplicity
    let fuel = startFuel, stops = 0, i = 0;
    while (fuel < target) {
        // Add all reachable stations to heap
        while (i < stations.length && stations[i][0] <= fuel) {
            heap.push(stations[i][1]);
            heap.sort((a,b)=>b-a); // max first
            i++;
        }
        if (!heap.length) return -1; // unreachable
        fuel += heap.shift(); // refuel at the richest station
        stops++;
    }
    return stops;
}
